with Base as (select *, date_trunc('week', event_time) as event_time_period from web_events where page != '/search'), web_events_stats as (select quarter(event_time_period) as event_period_quarter, max(duration_sec) - min(duration_sec) as duration_sec_range, min(duration_sec) as min_duration_sec from Base group by quarter(event_time_period)) select event_period_quarter, duration_sec_range from web_events_stats where duration_sec_range < 78 order by duration_sec_range desc, event_period_quarter limit 10
